function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function limit(s,max=159){const t=String(s).replace(/\s+/g,' ').trim();return t.length<=max?t:t.slice(0,max+1).replace(/\s+\S*$/,'').replace(/[.,;:!? -]+$/,'');}
function description(name){return limit('Explore '+name+' supplier listings at Sasta Milaga. Compare options, check destination availability and confirm stock, shipping and final price before ordering.');}
function replaceMeta(h,identity,value){
 const rx=new RegExp('(<meta\\s+(?:name|property)="'+identity+'"\\s+content=")([^"]*)(")','i');
 return rx.test(h)?h.replace(rx,(_m,a,_b,c)=>a+esc(value)+c):h;
}
function guide(c){
 const related=c.related.map(([slug,name])=>'<li><a href="'+STORE+'/c/global/'+slug+'.html">'+esc(name)+'</a></li>').join('');
 return '<section id="'+VERSION+'" class="sm-page sm-page--wide" aria-label="International shopping information and related categories">'+
 '<div class="sm-prose"><h2>'+esc(c.name)+': comparison and ordering guidance</h2>'+
 '<p>Compare the product options and factual details in these supplier listings. Product availability, exact specifications, delivery eligibility and final prices must be confirmed for the selected item.</p>'+
 '<h3>Can I order to my country?</h3><p>International delivery varies by product, variant, supplier and destination. Check availability for your specific country before ordering.</p>'+
 '<h3>What is included in the final price?</h3><p>Catalogue prices are estimates. Confirm selected variants, live stock, freight, taxes where applicable and final currency before paying.</p>'+
 '<h3>How can I choose the right option?</h3><p>Compare the actual item photos, material and dimensions where supplied. Review the shipping and returns terms before submitting an order.</p>'+
 '<nav aria-label="Related product categories"><h3>Explore related categories</h3><ul>'+related+'</ul></nav>'+
 '<p><a href="'+STORE+'/worldwide-shopping/">Worldwide shopping guidance</a> · <a href="'+STORE+'/shipping/">Delivery information</a> · <a href="'+STORE+'/returns/">Returns and refunds</a> · <a href="'+STORE+'/c/global/index.html">All global categories</a></p></div></section>';
}
export default {
 async fetch(request,env){
  if(!env.UPSTREAM)return new Response('SEO upstream unavailable',{status:503,headers:{'Cache-Control':'no-store'}});
  const u=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return env.UPSTREAM.fetch(request);
  const match=u.pathname.match(/^\/c\/global\/([a-z0-9-]+)\.html$/);
  if(!match||!Object.prototype.hasOwnProperty.call(CATEGORIES,match[1]))return env.UPSTREAM.fetch(request);
  const original=await env.UPSTREAM.fetch(request);
  if(request.method==='HEAD'||original.status!==200||!original.headers.get('content-type')?.toLowerCase().includes('text/html'))return original;
  let html=await original.text();
  if(html.length<500||html.length>1400000||html.includes('id="'+VERSION+'"'))return new Response(html,original);
  if(!html.includes('rel="canonical" href="'+STORE+u.pathname+'"')||!html.includes('</main>'))return new Response(html,original);
  const cat=CATEGORIES[match[1]],d=description(cat.name);
  html=replaceMeta(html,'description',d);
  html=replaceMeta(html,'og:description',d);
  html=replaceMeta(html,'twitter:description',d);
  html=html.replaceAll('Global items ship worldwide from our supplier network.','International delivery depends on the selected item and destination.');
  html=html.replaceAll('Global items are prepaid and delivered worldwide.','Delivery and payment options depend on the supplier, product and destination.');
  html=html.replace('</main>',guide(cat)+'</main>');
  const headers=new Headers(original.headers);
  headers.delete('content-length');headers.delete('etag');
  headers.set('x-sasta-semantic-seo','verified-category-v1');
  headers.set('content-type','text/html; charset=utf-8');
  return new Response(html,{status:original.status,headers});
 }
};